alter table public.site_settings add column if not exists paytr_enabled boolean not null default false, add column if not exists paytr_test_mode boolean not null default true, add column if not exists paytr_no_installment boolean not null default false, add column if not exists paytr_max_installment integer not null default 0;
alter table public.site_settings drop constraint if exists site_settings_paytr_max_installment_check;
alter table public.site_settings add constraint site_settings_paytr_max_installment_check check (paytr_max_installment between 0 and 12);
alter table public.purchase_requests add column if not exists checkout_token uuid not null default gen_random_uuid(), add column if not exists payment_provider text not null default 'bank_transfer', add column if not exists payment_status text not null default 'not_started', add column if not exists payment_provider_order_id text, add column if not exists payment_requested_amount integer, add column if not exists payment_paid_amount integer, add column if not exists payment_currency text not null default 'TL', add column if not exists payment_failure_code text, add column if not exists payment_failure_message text, add column if not exists payment_updated_at timestamptz not null default now();
alter table public.purchase_requests drop constraint if exists purchase_requests_payment_provider_check; alter table public.purchase_requests add constraint purchase_requests_payment_provider_check check (payment_provider in ('bank_transfer','paytr'));
alter table public.purchase_requests drop constraint if exists purchase_requests_payment_status_check; alter table public.purchase_requests add constraint purchase_requests_payment_status_check check (payment_status in ('not_started','pending','paid','failed','review'));
alter table public.purchase_requests drop constraint if exists purchase_requests_payment_currency_check; alter table public.purchase_requests add constraint purchase_requests_payment_currency_check check (payment_currency in ('TL','USD','EUR','GBP','RUB'));
create unique index if not exists purchase_requests_checkout_token_uidx on public.purchase_requests(checkout_token); create unique index if not exists purchase_requests_payment_provider_order_uidx on public.purchase_requests(payment_provider_order_id) where payment_provider_order_id is not null; create index if not exists purchase_requests_payment_status_idx on public.purchase_requests(payment_status,created_at desc);
create table if not exists public.payment_events(id uuid primary key default gen_random_uuid(),purchase_request_id uuid not null references public.purchase_requests(id) on delete cascade,provider text not null check(provider in('paytr')),merchant_oid text not null,event_status text not null,payment_amount integer,total_amount integer,currency text,payment_type text,failure_code text,failure_message text,test_mode boolean,received_at timestamptz not null default now());
create index if not exists payment_events_purchase_idx on public.payment_events(purchase_request_id,received_at desc); create index if not exists payment_events_merchant_oid_idx on public.payment_events(merchant_oid,received_at desc); alter table public.payment_events enable row level security; revoke all on table public.payment_events from public,anon,authenticated; grant select on table public.payment_events to authenticated; drop policy if exists payment_events_admin_select on public.payment_events; create policy payment_events_admin_select on public.payment_events for select to authenticated using((select private.is_admin()));
-- PayTR mutation RPCs are intentionally service-role only. The application verifies PayTR signatures before calling callback processing.
create or replace function public.prepare_paytr_payment(p_purchase_id uuid,p_checkout_token uuid,p_merchant_oid text) returns table(purchase_id uuid,merchant_oid text,product_title text,product_price numeric,customer_name text,customer_email text,customer_phone text,customer_address text,requested_amount integer) language plpgsql security definer set search_path='' as $$ declare v_order public.purchase_requests%rowtype;v_product public.products%rowtype;v_enabled boolean;begin select paytr_enabled into v_enabled from public.site_settings where id=true;if coalesce(v_enabled,false)=false then raise exception 'PAYTR_DISABLED';end if;if p_merchant_oid is null or p_merchant_oid!~'^[A-Za-z0-9]{6,64}$' then raise exception 'INVALID_MERCHANT_OID';end if;select * into v_order from public.purchase_requests where id=p_purchase_id and checkout_token=p_checkout_token for update;if not found then raise exception 'ORDER_NOT_FOUND';end if;if v_order.product_price is null or v_order.product_price<=0 then raise exception 'INVALID_ORDER_AMOUNT';end if;if v_order.status in('paid','preparing','shipped','completed') or v_order.payment_status='paid' then raise exception 'ORDER_ALREADY_PAID';end if;select * into v_product from public.products where id=v_order.product_id for update;if not found or v_product.publication_status<>'published' or v_product.stock_status not in('in_stock','reserved') then raise exception 'PRODUCT_NOT_AVAILABLE';end if;if exists(select 1 from public.purchase_requests p where p.product_id=v_order.product_id and p.id<>v_order.id and p.status in('awaiting_payment','paid','preparing','shipped','completed')) then raise exception 'PRODUCT_RESERVED_BY_ANOTHER_ORDER';end if;update public.products set stock_status='reserved',updated_at=now() where id=v_order.product_id;update public.purchase_requests set payment_method='paytr',payment_provider='paytr',payment_status='pending',payment_provider_order_id=p_merchant_oid,payment_requested_amount=round(v_order.product_price*100)::integer,payment_paid_amount=null,payment_currency='TL',payment_failure_code=null,payment_failure_message=null,payment_updated_at=now(),status='awaiting_payment',status_changed_at=now(),cancelled_at=null,updated_at=now() where id=v_order.id;return query select v_order.id,p_merchant_oid,v_order.product_title,v_order.product_price,v_order.customer_name,v_order.customer_email,v_order.customer_phone,concat_ws(', ',v_order.address_line,v_order.district,v_order.city),round(v_order.product_price*100)::integer;end;$$;
create or replace function public.abort_paytr_payment(p_purchase_id uuid,p_merchant_oid text,p_reason text default null) returns boolean language plpgsql security definer set search_path='' as $$ declare v_order public.purchase_requests%rowtype;begin select * into v_order from public.purchase_requests where id=p_purchase_id and payment_provider_order_id=p_merchant_oid for update;if not found or v_order.payment_status='paid' then return false;end if;update public.purchase_requests set payment_status='failed',payment_failure_message=left(coalesce(p_reason,'PAYTR token request failed'),500),payment_provider_order_id=null,payment_updated_at=now(),status='new',status_changed_at=now(),updated_at=now() where id=v_order.id;update public.products set stock_status='in_stock',updated_at=now() where id=v_order.product_id and stock_status='reserved' and not exists(select 1 from public.purchase_requests p where p.product_id=v_order.product_id and p.id<>v_order.id and p.status in('awaiting_payment','paid','preparing','shipped','completed'));return true;end;$$;
create or replace function public.process_paytr_callback(p_merchant_oid text,p_status text,p_payment_amount integer,p_total_amount integer,p_currency text,p_payment_type text,p_failure_code text default null,p_failure_message text default null,p_test_mode boolean default false) returns text language plpgsql security definer set search_path='' as $$ declare v_order public.purchase_requests%rowtype;begin select * into v_order from public.purchase_requests where payment_provider='paytr' and payment_provider_order_id=p_merchant_oid for update;if not found then raise exception 'ORDER_NOT_FOUND';end if;insert into public.payment_events(purchase_request_id,provider,merchant_oid,event_status,payment_amount,total_amount,currency,payment_type,failure_code,failure_message,test_mode) values(v_order.id,'paytr',p_merchant_oid,p_status,p_payment_amount,p_total_amount,p_currency,p_payment_type,left(p_failure_code,100),left(p_failure_message,500),p_test_mode);if v_order.payment_status='paid' then return 'duplicate';end if;if p_status='success' then if p_payment_amount is distinct from v_order.payment_requested_amount then update public.purchase_requests set payment_status='review',payment_paid_amount=p_total_amount,payment_failure_code='AMOUNT_MISMATCH',payment_failure_message='PayTR callback payment_amount does not match order amount',payment_updated_at=now(),updated_at=now() where id=v_order.id;return 'review';end if;update public.purchase_requests set payment_status='paid',payment_paid_amount=p_total_amount,payment_currency=coalesce(nullif(p_currency,''),'TL'),payment_failure_code=null,payment_failure_message=null,payment_updated_at=now(),status='paid',status_changed_at=now(),payment_received_at=coalesce(payment_received_at,now()),updated_at=now() where id=v_order.id;return 'paid';end if;update public.purchase_requests set payment_status='failed',payment_paid_amount=p_total_amount,payment_failure_code=left(p_failure_code,100),payment_failure_message=left(p_failure_message,500),payment_updated_at=now(),status='cancelled',status_changed_at=now(),cancelled_at=coalesce(cancelled_at,now()),updated_at=now() where id=v_order.id;update public.products set stock_status='in_stock',updated_at=now() where id=v_order.product_id and stock_status='reserved' and not exists(select 1 from public.purchase_requests p where p.product_id=v_order.product_id and p.id<>v_order.id and p.status in('awaiting_payment','paid','preparing','shipped','completed'));return 'failed';end;$$;
revoke all on function public.prepare_paytr_payment(uuid,uuid,text) from public,anon,authenticated;revoke all on function public.abort_paytr_payment(uuid,text,text) from public,anon,authenticated;revoke all on function public.process_paytr_callback(text,text,integer,integer,text,text,text,text,boolean) from public,anon,authenticated;grant execute on function public.prepare_paytr_payment(uuid,uuid,text) to service_role;grant execute on function public.abort_paytr_payment(uuid,text,text) to service_role;grant execute on function public.process_paytr_callback(text,text,integer,integer,text,text,text,text,boolean) to service_role;
